<?php
require_once __DIR__.'/../../includes/auth.php';
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  $action=$_POST['action']??'';$id=(int)($_POST['id']??0);
  if(in_array($action,['create','update'],true)){
   $name=trim($_POST['category_name']??'');if($name==='')throw new RuntimeException('Nama kategori wajib diisi.');
   $check=$pdo->prepare("SELECT id FROM transaction_categories WHERE LOWER(TRIM(category_name))=LOWER(TRIM(:name)) AND id<>:id LIMIT 1");$check->execute([':name'=>$name,':id'=>$id]);if($check->fetch())throw new RuntimeException('Nama kategori sudah digunakan.');
   if($action==='create')$pdo->prepare("INSERT INTO transaction_categories(category_name,type,status) VALUES(:name,'both','active')")->execute([':name'=>$name]);
   else $pdo->prepare("UPDATE transaction_categories SET category_name=:name,type='both' WHERE id=:id")->execute([':name'=>$name,':id'=>$id]);
  }elseif($action==='toggle'){$pdo->prepare("UPDATE transaction_categories SET status=IF(status='active','inactive','active') WHERE id=:id")->execute([':id'=>$id]);}
  elseif($action==='delete'){$used=$pdo->prepare("SELECT COUNT(*) FROM transactions WHERE category_id=:id");$used->execute([':id'=>$id]);if((int)$used->fetchColumn()>0)throw new RuntimeException('Kategori sudah digunakan dan tidak boleh dihapus. Nonaktifkan sebagai gantinya.');$pdo->prepare("DELETE FROM transaction_categories WHERE id=:id")->execute([':id'=>$id]);}
  redirect('pages/master/categories.php?saved=1');
 }catch(Throwable $e){$error=$e->getMessage();}
}
$q=trim($_GET['q']??'');$params=[];$where='';if($q!==''){$where='WHERE c.category_name LIKE :q';$params[':q']='%'.$q.'%';}
$stmt=$pdo->prepare("SELECT c.*,COUNT(t.id) usage_count FROM transaction_categories c LEFT JOIN transactions t ON t.category_id=c.id $where GROUP BY c.id ORDER BY c.status,c.category_name");$stmt->execute($params);$categories=$stmt->fetchAll(PDO::FETCH_ASSOC);
$pageTitle='Kategori Transaksi - Nukari';require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';?>
<main class="main-content"><div class="page-header d-flex justify-content-between align-items-center flex-wrap gap-3"><div><h1 class="fw-bold mb-1">Kategori Transaksi</h1><p class="text-muted mb-0">Kategori universal yang dapat digunakan pada pemasukan maupun pengeluaran.</p></div><button class="btn btn-nukari" data-bs-toggle="modal" data-bs-target="#categoryModal"><i class="bi bi-plus-circle me-1"></i> Tambah Kategori</button></div>
<?php if($error):?><div class="alert alert-danger rounded-4"><?=htmlspecialchars($error);?></div><?php endif;?><?php if(!empty($_GET['saved'])):?><div class="alert alert-success rounded-4 py-2">Kategori berhasil diperbarui.</div><?php endif;?>
<div class="panel mb-4"><form class="d-flex gap-2"><input name="q" value="<?=htmlspecialchars($q);?>" class="form-control" placeholder="Cari nama kategori..."><button class="btn btn-outline-success"><i class="bi bi-search"></i></button></form></div>
<div class="panel"><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Nama Kategori</th><th>Dipakai</th><th>Status</th><th class="text-end">Aksi</th></tr></thead><tbody><?php foreach($categories as $c):?><tr><td class="fw-semibold"><?=htmlspecialchars($c['category_name']);?></td><td><?=(int)$c['usage_count'];?> transaksi</td><td><?=$c['status']==='active'?'<span class="badge bg-success">Aktif</span>':'<span class="badge bg-secondary">Nonaktif</span>';?></td><td class="text-end"><button class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#categoryModal" data-category='<?=htmlspecialchars(json_encode($c),ENT_QUOTES,'UTF-8');?>'>Edit</button> <form method="POST" class="d-inline"><?=csrf_field();?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$c['id'];?>"><button class="btn btn-sm btn-outline-secondary"><?=$c['status']==='active'?'Nonaktifkan':'Aktifkan';?></button></form><?php if((int)$c['usage_count']===0):?> <form method="POST" class="d-inline" onsubmit="return confirm('Hapus kategori ini?')"><?=csrf_field();?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$c['id'];?>"><button class="btn btn-sm btn-outline-danger">Hapus</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></main>
<div class="modal fade" id="categoryModal"><div class="modal-dialog modal-dialog-centered"><form method="POST" class="modal-content rounded-4 border-0"><?=csrf_field();?><input type="hidden" name="action" id="categoryAction" value="create"><input type="hidden" name="id" id="categoryId"><div class="modal-header"><h5 class="modal-title fw-bold" id="categoryTitle">Tambah Kategori</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label">Nama Kategori</label><input name="category_name" id="categoryName" class="form-control" required placeholder="Contoh: RT/RW, Listrik, Internet"><div class="form-text">Kategori dapat digunakan pada transaksi pemasukan maupun pengeluaran.</div></div><div class="modal-footer"><button class="btn btn-light" data-bs-dismiss="modal">Batal</button><button class="btn btn-nukari">Simpan</button></div></form></div></div>
<script>document.getElementById('categoryModal')?.addEventListener('show.bs.modal',e=>{const c=e.relatedTarget?.dataset.category?JSON.parse(e.relatedTarget.dataset.category):null;document.getElementById('categoryAction').value=c?'update':'create';document.getElementById('categoryId').value=c?.id||'';document.getElementById('categoryName').value=c?.category_name||'';document.getElementById('categoryTitle').textContent=c?'Edit Kategori':'Tambah Kategori';});</script>
<?php require_once __DIR__.'/../../includes/footer.php';?>
